        assert((pthread_mutex_lock(&fork_m[high])) == 0); /* entry section */
        ++eaten[id]; /* both forks held */
        assert((pthread_mutex_unlock(&fork_m[high])) == 0);
        assert((pthread_mutex_unlock(&fork_m[low])) == 0); /* exit section */
    } return NULL;
}
int main(void) {
