    for (int i=0; i<N; ++i) { ids[i]=i; assert((pthread_mutex_init(&fork_m[i],NULL)) == 0); }
    for (int i=0; i<N; ++i) assert((pthread_create(&t[i],NULL,diner,&ids[i])) == 0);
    for (int i=0; i<N; ++i) { assert((pthread_join(t[i],NULL)) == 0); assert(eaten[i]==MEALS); total+=eaten[i]; }
    printf("meals=%d\n",total);
    for (int i=0; i<N; ++i) assert((pthread_mutex_destroy(&fork_m[i])) == 0);
    return 0;
}
```

