    for (int i=0; i<N; ++i) assert((pthread_join(t[i],NULL)) == 0);
    assert((pthread_mutex_lock(&m)) == 0); closed=1; assert((pthread_mutex_unlock(&m)) == 0); assert(sem_post(&arrivals) == 0);
