question:
Is joining in main enough to keep launch’s stack argument alive? Assume successful API calls except where the program violates an object’s ownership or lifetime rules.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static int copied;
static void *worker(void *p) { copied=*(int *)p; return NULL; }
static pthread_t launch(void) {
    int local_job=7; pthread_t t;
    ck(pthread_create(&t,NULL,worker,&local_job));
    return t;
}
int main(void) {
    pthread_t t=launch();
    ck(pthread_join(t,NULL));
    assert(copied==7); return 0;
}
```

answer:
Verdict: bug found

Line 24: `ck(pthread_create(&t,NULL,worker,&local_job));`
Line 25: `return t;`

The helper returns before its worker is guaranteed to finish reading local storage. Main’s later join cannot extend the ended stack lifetime.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | launch creates worker with &local_job |  | argument points into launch’s stack |
| 2 | launch returns |  | local_job lifetime ends |
| 3 |  | worker dereferences argument | dangling pointer; joining later cannot restore lifetime |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -22,10 +22,11 @@
 static pthread_t launch(void) {
     int local_job=7; pthread_t t;
     ck(pthread_create(&t,NULL,worker,&local_job));
+    ck(pthread_join(t,NULL));
     return t;
 }
 int main(void) {
     pthread_t t=launch();
-    ck(pthread_join(t,NULL));
+    (void)t; /* launch has already joined */
     assert(copied==7); return 0;
 }
```

Join inside launch while local_job exists, then do not join the already-joined identifier again. An alternative is to keep an argument object in main through its join.

