question:
Does joining the producer guarantee the pipeline’s final result is ready? Assume successful API calls except where the program violates an object’s ownership or lifetime rules.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static sem_t full;
static int packet,result;
static void *producer(void *p) { (void)p; packet=5; V(full); return NULL; }
static void *consumer(void *p) { (void)p; P(full); result=packet*2; return NULL; }
int main(void) {
    pthread_t p,c; SO(sem_init(&full,0,0));
    ck(pthread_create(&p,NULL,producer,NULL)); ck(pthread_create(&c,NULL,consumer,NULL));
    ck(pthread_join(p,NULL));
    printf("result=%d\n",result);
    return 0;
}
```

answer:
Verdict: bug found

Line 28: `printf("result=%d\n",result);`

Producer completion proves input publication, not consumer completion. Main may read result before or during the consumer’s write.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | producer signals full |  | packet published |
| 2 |  | main joins producer | consumer can still be pending |
| 3 |  | main reads result | final transformation not ordered complete |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -25,6 +25,8 @@
     pthread_t p,c; SO(sem_init(&full,0,0));
     ck(pthread_create(&p,NULL,producer,NULL)); ck(pthread_create(&c,NULL,consumer,NULL));
     ck(pthread_join(p,NULL));
+    ck(pthread_join(c,NULL));
     printf("result=%d\n",result);
+    SO(sem_destroy(&full));
     return 0;
 }
```

Join the consumer before reading its output and before destroying the event semaphore. Distinct pipeline stages need their own completion edges.

