question:
Is detach a replacement for waiting before freeing a job argument? Assume successful API calls except where the program violates an object’s ownership or lifetime rules.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static void *worker(void *p) {
    int *job=p; *job=99; return NULL;
}
int main(void) {
    pthread_t t; int *job=malloc(sizeof *job); assert(job); *job=0;
    ck(pthread_create(&t,NULL,worker,job));
    ck(pthread_detach(t));
    free(job);
    return 0;
}
```

answer:
Verdict: bug found

Line 26: `ck(pthread_detach(t));`
Line 27: `free(job);`

Detaching only changes thread-resource reclamation. It does not keep the pointed-to job alive or wait for the worker to finish.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | worker created with heap job |  | worker may not have started |
| 2 |  | main detaches worker | detachment establishes no completion wait |
| 3 |  | main frees job | storage released |
| 4 | worker writes *job |  | possible use-after-free |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -23,7 +23,7 @@
 int main(void) {
     pthread_t t; int *job=malloc(sizeof *job); assert(job); *job=0;
     ck(pthread_create(&t,NULL,worker,job));
-    ck(pthread_detach(t));
+    ck(pthread_join(t,NULL));
     free(job);
     return 0;
 }
```

Retain a joinable thread and join before free. The job has no user after the join; a detached design would instead need an explicit ownership-transfer or completion protocol.

