Why can opposite bank transfers deadlock despite protecting both accounts? Assume successful API calls except where the program violates an object’s ownership or lifetime rules.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static pthread_mutex_t account[2]={PTHREAD_MUTEX_INITIALIZER,PTHREAD_MUTEX_INITIALIZER};
static int balance[2]={5,5};
static void move(int from) {
    int to=1-from; ck(pthread_mutex_lock(&account[from])); ck(pthread_mutex_lock(&account[to]));
    --balance[from]; ++balance[to];
    ck(pthread_mutex_unlock(&account[to])); ck(pthread_mutex_unlock(&account[from]));
}
static void *a(void *p) { (void)p; move(0); return NULL; }
static void *b(void *p) { (void)p; move(1); return NULL; }
int main(void) {
    pthread_t x,y;

    ck(pthread_create(&x,NULL,a,NULL));
    ck(pthread_create(&y,NULL,b,NULL));
    ck(pthread_join(x,NULL));
    ck(pthread_join(y,NULL));
    assert(balance[0]+balance[1]==10);
    ck(pthread_mutex_destroy(&account[0])); ck(pthread_mutex_destroy(&account[1]));
    return 0;
}
```

answer:
Verdict: bug found

Line 23: `int to=1-from; ck(pthread_mutex_lock(&account[from])); ck(pthread_mutex_lock(&account[to]));`

Source-first order reverses when transfer direction reverses, satisfying circular wait.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | lock(account[0]) succeeds |  | account0=A |
| 2 |  | lock(account[1]) succeeds | account1=B |
| 3 | lock(account[1]) blocks |  | A waits for B |
| 4 |  | lock(account[0]) blocks | B waits for A |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -20,9 +20,9 @@
 static pthread_mutex_t account[2]={PTHREAD_MUTEX_INITIALIZER,PTHREAD_MUTEX_INITIALIZER};
 static int balance[2]={5,5};
 static void move(int from) {
-    int to=1-from; ck(pthread_mutex_lock(&account[from])); ck(pthread_mutex_lock(&account[to]));
+    int to=1-from; ck(pthread_mutex_lock(&account[0])); ck(pthread_mutex_lock(&account[1]));
     --balance[from]; ++balance[to];
-    ck(pthread_mutex_unlock(&account[to])); ck(pthread_mutex_unlock(&account[from]));
+    ck(pthread_mutex_unlock(&account[1])); ck(pthread_mutex_unlock(&account[0]));
 }
 static void *a(void *p) { (void)p; move(0); return NULL; }
 static void *b(void *p) { (void)p; move(1); return NULL; }
```

Acquire account0 then account1 for every transfer, while still using from/to for the actual debit and credit. Reverse-order exits release both after the invariant is restored.

