static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static pthread_mutex_t queue=PTHREAD_MUTEX_INITIALIZER,log_m=PTHREAD_MUTEX_INITIALIZER;
static int logged;
static void *a(void *p) {
    (void)p; ck(pthread_mutex_lock(&queue)); ck(pthread_mutex_lock(&log_m));
    ++logged; ck(pthread_mutex_unlock(&log_m)); ck(pthread_mutex_unlock(&queue)); return NULL;
}
static void *b(void *p) {
    (void)p; ck(pthread_mutex_lock(&log_m));
    ck(pthread_mutex_lock(&queue)); assert(logged>=0); ck(pthread_mutex_unlock(&queue));
    ck(pthread_mutex_unlock(&log_m)); return NULL;
