```diff
--- prog.c
+++ prog.c (fixed)
@@ -24,9 +24,8 @@
     ++logged; ck(pthread_mutex_unlock(&log_m)); ck(pthread_mutex_unlock(&queue)); return NULL;
 }
 static void *b(void *p) {
-    (void)p; ck(pthread_mutex_lock(&log_m));
-    ck(pthread_mutex_lock(&queue)); assert(logged>=0); ck(pthread_mutex_unlock(&queue));
-    ck(pthread_mutex_unlock(&log_m)); return NULL;
+    (void)p; ck(pthread_mutex_lock(&queue)); ck(pthread_mutex_lock(&log_m));
+    assert(logged>=0); ck(pthread_mutex_unlock(&log_m)); ck(pthread_mutex_unlock(&queue)); return NULL;
 }
 int main(void) {
     pthread_t x,y;
```

The callback uses the same queue-before-log hierarchy as the producer. A callback boundary does not exempt code from the global entry order.

