question:
Why is this plain shutdown flag not a valid thread-stop protocol? Assume successful API calls except where the program violates an object’s ownership or lifetime rules.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <signal.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
#define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
#define V(s) SO(sem_post(&(s)))
static int stop;
static unsigned work;
static void *a(void *p) {
    (void)p; while(!stop) ++work; return NULL;
}
static void *b(void *p) { (void)p; stop=1; return NULL; }
int main(void) {
    pthread_t x,y;

    ck(pthread_create(&x,NULL,a,NULL));
    ck(pthread_create(&y,NULL,b,NULL));
    ck(pthread_join(x,NULL));
    ck(pthread_join(y,NULL));
    printf("work=%u\n",work);

    return 0;
}
```

answer:
Verdict: bug found

Line 23: `(void)p; while(!stop) ++work; return NULL;`
Line 25: `static void *b(void *p) { (void)p; stop=1; return NULL; }`

The worker and controller conflict on an ordinary flag. The C data race permits no portable visibility or loop-termination claim; volatile would not repair it.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | read ordinary stop -> 0 |  | no ordering edge |
| 2 |  | write ordinary stop=1 | conflicts with A’s reads |
| 3 | continue polling ordinary stop |  | C data race; termination not guaranteed |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -17,12 +17,12 @@
 #define SO(x) do { if ((x)==-1) { perror(#x); exit(1); } } while (0)
 #define P(s) do { int e; do { e=sem_wait(&(s)); } while (e==-1 && errno==EINTR); if (e==-1) { perror("sem_wait"); exit(1); } } while (0)
 #define V(s) SO(sem_post(&(s)))
-static int stop;
+static atomic_int stop;
 static unsigned work;
 static void *a(void *p) {
-    (void)p; while(!stop) ++work; return NULL;
+    (void)p; while(!atomic_load_explicit(&stop,memory_order_relaxed)) ++work; return NULL;
 }
-static void *b(void *p) { (void)p; stop=1; return NULL; }
+static void *b(void *p) { (void)p; atomic_store_explicit(&stop,1,memory_order_relaxed); return NULL; }
 int main(void) {
     pthread_t x,y;

```

All stop accesses are atomic. Relaxed ordering suffices because stop publishes no separate payload; work has one writer and is read only after join. Progress still requires the controller to run.

