Plan: Reserve capacity before locking; finish both producers before inserting termination parcels.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
enum { CAP=3, ITEMS=8 };
static int q[CAP],head,tail,seen[ITEMS],ids[2]={0,1};
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static sem_t empty,full;
static void put(int x) {
    assert(sem_wait(&(empty)) == 0); assert((pthread_mutex_lock(&m)) == 0);
    q[tail]=x; tail=(tail+1)%CAP;
    assert((pthread_mutex_unlock(&m)) == 0); assert(sem_post(&(full)) == 0);
}
static int get(void) {
    assert(sem_wait(&(full)) == 0); assert((pthread_mutex_lock(&m)) == 0);
    int x=q[head]; head=(head+1)%CAP;
    assert((pthread_mutex_unlock(&m)) == 0); assert(sem_post(&(empty)) == 0); return x;
}
static void *producer(void *p) {
    int id=*(int *)p; for(int j=0;j<4;j++) put(4*id+j); return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for(int j=0;j<=ITEMS;j++) {
        int x=get(); if(x==-1) return NULL;
        assert((pthread_mutex_lock(&m)) == 0); assert(x>=0 && x<ITEMS); ++seen[x];
        assert((pthread_mutex_unlock(&m)) == 0);
    }
    abort();
}
int main(void) {
    pthread_t p[2],c[2]; assert((sem_init(&empty,0,CAP)) != -1); assert((sem_init(&full,0,0)) != -1);
    for(int i=0;i<2;i++) assert((pthread_create(&c[i],NULL,consumer,NULL)) == 0);
    for(int i=0;i<2;i++) assert((pthread_create(&p[i],NULL,producer,&ids[i])) == 0);
    for(int i=0;i<2;i++) assert((pthread_join(p[i],NULL)) == 0);
    put(-1); put(-1);
    for(int i=0;i<2;i++) assert((pthread_join(c[i],NULL)) == 0);
    for(int i=0;i<ITEMS;i++) assert(seen[i]==1);
    assert((sem_destroy(&empty)) != -1); assert((sem_destroy(&full)) != -1); assert((pthread_mutex_destroy(&m)) == 0);
    puts("all parcels delivered once"); return 0;
}
```

Why it is correct: empty/full maintain capacity and publication, while m protects queue indexes and the identity audit. No capacity wait holds m. A consumer exits only on its own termination parcel, so joins cannot strand another consumer.

