Plan: Keep closure in the queue monitor rather than encoding it as an item.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t ne=PTHREAD_COND_INITIALIZER,nf=PTHREAD_COND_INITIALIZER;
static int q[2],head,tail,count,closed,delivered,ids[3]={0,1,2};
static void *producer(void *p) {
    int id=*(int *)p;
    for(int j=0;j<2;j++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==2) assert((pthread_cond_wait(&nf,&m)) == 0);
        q[tail]=id*2+j; tail=(tail+1)%2; ++count;
        assert((pthread_cond_signal(&ne)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    } return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for(int j=0;j<=6;j++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==0 && !closed) assert((pthread_cond_wait(&ne,&m)) == 0);
        if(count==0) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        assert(q[head]>=0); head=(head+1)%2; --count; ++delivered;
        assert((pthread_cond_signal(&nf)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    } abort();
}
int main(void) {
    pthread_t p[3],c[2];
    for(int i=0;i<2;i++) assert((pthread_create(&c[i],NULL,consumer,NULL)) == 0);
    for(int i=0;i<3;i++) assert((pthread_create(&p[i],NULL,producer,&ids[i])) == 0);
    for(int i=0;i<3;i++) assert((pthread_join(p[i],NULL)) == 0);
    assert((pthread_mutex_lock(&m)) == 0); closed=1; assert((pthread_cond_broadcast(&ne)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0);
    for(int i=0;i<2;i++) assert((pthread_join(c[i],NULL)) == 0);
    assert(count==0 && delivered==6);
    assert((pthread_cond_destroy(&ne)) == 0); assert((pthread_cond_destroy(&nf)) == 0);
    assert((pthread_mutex_destroy(&m)) == 0); puts("orders drained after closure"); return 0;
}
```

Why it is correct: All predicates and queue operations use m. Each wait releases m atomically and rechecks in a while loop. Closure broadcasts to all consumers, and empty plus closed is the exit predicate; pending orders are not discarded.

