Plan: Protect the reader cohort count and reserve the catalog for the whole cohort.

```c
#include <pthread.h>
#include <semaphore.h>
#include <assert.h>
static sem_t resource;
static pthread_mutex_t cm=PTHREAD_MUTEX_INITIALIZER;
static int readers,record,checksum;
static void *read_catalog(void *p) {
    (void)p;
    assert((pthread_mutex_lock(&cm)) == 0); if(++readers==1) assert(sem_wait(&(resource)) == 0);
    assert((pthread_mutex_unlock(&cm)) == 0);
    assert(checksum==(record^0x55));
    assert((pthread_mutex_lock(&cm)) == 0); if(--readers==0) assert(sem_post(&(resource)) == 0);
    assert((pthread_mutex_unlock(&cm)) == 0); return NULL;
}
static void *replace(void *p) {
    (void)p; assert(sem_wait(&(resource)) == 0); record=42; checksum=record^0x55; assert(sem_post(&(resource)) == 0); return NULL;
}
int main(void) {
    pthread_t t[4]; checksum=record^0x55; assert((sem_init(&resource,0,1)) != -1);
    for(int i=0;i<3;i++) assert((pthread_create(&t[i],NULL,read_catalog,NULL)) == 0);
    assert((pthread_create(&t[3],NULL,replace,NULL)) == 0);
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(readers==0 && record==42 && checksum==(record^0x55));
    assert((sem_destroy(&resource)) != -1); assert((pthread_mutex_destroy(&cm)) == 0); return 0;
}
```

Why it is correct: cm serializes first/last transitions. resource excludes the writer while any reader uses the record. The writer does not need cm, so a first reader waiting with cm held creates no cycle. Finite readers finish; reader preference is not starvation-free under infinite arrivals.

