Plan: Track both active users and waiting writers under one monitor mutex.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int active_readers,writer,waiting_writers,value;
static void *read_config(void *p) {
    (void)p; assert((pthread_mutex_lock(&m)) == 0);
    while(writer || waiting_writers) assert((pthread_cond_wait(&cv,&m)) == 0);
    ++active_readers; assert((pthread_mutex_unlock(&m)) == 0);
    assert(value>=0 && value<=2);
    assert((pthread_mutex_lock(&m)) == 0); --active_readers;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
static void *write_config(void *p) {
    (void)p; assert((pthread_mutex_lock(&m)) == 0); ++waiting_writers;
    while(writer || active_readers) assert((pthread_cond_wait(&cv,&m)) == 0);
    --waiting_writers; writer=1; assert((pthread_mutex_unlock(&m)) == 0);
    ++value;
    assert((pthread_mutex_lock(&m)) == 0); writer=0;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
int main(void) {
    pthread_t r[2],w[2];
    for(int i=0;i<2;i++) assert((pthread_create(&r[i],NULL,read_config,NULL)) == 0);
    for(int i=0;i<2;i++) assert((pthread_create(&w[i],NULL,write_config,NULL)) == 0);
    for(int i=0;i<2;i++) { assert((pthread_join(r[i],NULL)) == 0); assert((pthread_join(w[i],NULL)) == 0); }
    assert(value==2 && !writer && active_readers==0);
    assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: A queued writer blocks new reader admission; active readers drain before a writer enters its data critical section. Admission and exit handoffs under m order data accesses. The finite program progresses, although infinite writer traffic could starve readers.

