Plan: Assign tickets at arrival; a ticket at the front waits for the resource condition it needs.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static unsigned issued,next;
static int readers,writer,value,kind[5]={0,0,1,0,1};
static void *user(void *p) {
    int w=*(int *)p; assert((pthread_mutex_lock(&m)) == 0); unsigned mine=issued++;
    while(mine!=next || writer || (w && readers)) assert((pthread_cond_wait(&cv,&m)) == 0);
    ++next; if(w) writer=1; else ++readers;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    if(w) ++value; else assert(value>=0 && value<=2);
    assert((pthread_mutex_lock(&m)) == 0); if(w) writer=0; else --readers;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
int main(void) {
    pthread_t t[5];
    for(int i=0;i<5;i++) assert((pthread_create(&t[i],NULL,user,&kind[i])) == 0);
    for(int i=0;i<5;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(value==2 && next==issued && !writer && readers==0);
    assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Only the next ticket can be admitted. Readers advance the admission ticket and may overlap; a front writer stops later readers until the active cohort drains. Predicate loops and broadcasts avoid lost wakeups. FIFO admission assumes ticket holders are scheduled and eventually finish.

