Plan: Queue accepted customer IDs and wait on that customer’s own service predicate.

```c
#include <pthread.h>
#include <stdlib.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t arrivals=PTHREAD_COND_INITIALIZER,done=PTHREAD_COND_INITIALIZER;
static int q[2],head,tail,count,closed,served[5],ids[5],accepted,rejected;
static void *customer(void *p) {
    int id=*(int *)p; assert((pthread_mutex_lock(&m)) == 0);
    if(count==2) { ++rejected; assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
    q[tail]=id; tail=(tail+1)%2; ++count; ++accepted;
    assert((pthread_cond_signal(&arrivals)) == 0);
    while(!served[id]) assert((pthread_cond_wait(&done,&m)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
static void *barber(void *p) {
    (void)p;
    for(int jobs=0;jobs<=5;jobs++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==0 && !closed) assert((pthread_cond_wait(&arrivals,&m)) == 0);
        if(count==0) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        int id=q[head]; head=(head+1)%2; --count; served[id]=1;
        assert((pthread_cond_broadcast(&done)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    } abort();
}
int main(void) {
    pthread_t b,c[5]; assert((pthread_create(&b,NULL,barber,NULL)) == 0);
    for(int i=0;i<5;i++) { ids[i]=i; assert((pthread_create(&c[i],NULL,customer,&ids[i])) == 0); }
    for(int i=0;i<5;i++) assert((pthread_join(c[i],NULL)) == 0);
    assert((pthread_mutex_lock(&m)) == 0); closed=1; assert((pthread_cond_signal(&arrivals)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    assert((pthread_join(b,NULL)) == 0); int total=0;
    for(int i=0;i<5;i++) total+=served[i];
    assert(total==accepted && accepted+rejected==5);
    assert((pthread_cond_destroy(&arrivals)) == 0); assert((pthread_cond_destroy(&done)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: One mutex protects chairs, queue, closure and service state. A completion broadcast may wake everyone, but only the served customer’s while predicate passes. Main closes only after every customer joins, then wakes and joins the barber.

