Plan: Serialize ingredient pairing and allow only one agent round before its completion acknowledgment.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <assert.h>
static sem_t ingredient[3],smoker[3],completed;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static int present[3],closed,ids[3],smoked;
static void *pusher(void *p) {
    int i=*(int *)p;
    for(int k=0;k<=6;k++) {
        assert(sem_wait(&(ingredient[i])) == 0); assert((pthread_mutex_lock(&m)) == 0);
        if(closed) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        int mate=-1;
        for(int j=0;j<3;j++) if(j!=i && present[j]) mate=j;
        if(mate>=0) { present[mate]=0; assert(sem_post(&(smoker[3-i-mate])) == 0); }
        else present[i]=1;
        assert((pthread_mutex_unlock(&m)) == 0);
    } abort();
}
static void *smoke(void *p) {
    int i=*(int *)p;
    for(int k=0;k<=3;k++) {
        assert(sem_wait(&(smoker[i])) == 0); assert((pthread_mutex_lock(&m)) == 0);
        if(closed) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        ++smoked; assert((pthread_mutex_unlock(&m)) == 0); assert(sem_post(&(completed)) == 0);
    } abort();
}
int main(void) {
    pthread_t push[3],s[3]; assert((sem_init(&completed,0,0)) != -1);
    for(int i=0;i<3;i++) { ids[i]=i; assert((sem_init(&ingredient[i],0,0)) != -1); assert((sem_init(&smoker[i],0,0)) != -1); }
    for(int i=0;i<3;i++) { assert((pthread_create(&push[i],NULL,pusher,&ids[i])) == 0); assert((pthread_create(&s[i],NULL,smoke,&ids[i])) == 0); }
    for(int missing=0;missing<3;missing++) { assert(sem_post(&(ingredient[(missing+1)%3])) == 0); assert(sem_post(&(ingredient[(missing+2)%3])) == 0); assert(sem_wait(&(completed)) == 0); }
    assert((pthread_mutex_lock(&m)) == 0); closed=1; assert((pthread_mutex_unlock(&m)) == 0);
    for(int i=0;i<3;i++) assert(sem_post(&(ingredient[i])) == 0);
    for(int i=0;i<3;i++) assert((pthread_join(push[i],NULL)) == 0);
    for(int i=0;i<3;i++) assert(sem_post(&(smoker[i])) == 0);
    for(int i=0;i<3;i++) assert((pthread_join(s[i],NULL)) == 0);
    assert(smoked==3);
    for(int i=0;i<3;i++) { assert((sem_destroy(&ingredient[i])) != -1); assert((sem_destroy(&smoker[i])) != -1); }
    assert((sem_destroy(&completed)) != -1); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Pushers pair two distinct arrivals under m and post exactly the missing smoker’s semaphore. The agent posts ingredients before waiting for completion, so no initial circular wait occurs. Closure is protected and sends a final wakeup to each finite waiter.

