Plan: Transfer node ownership from producer to queue to consumer, then free it after removal.

```c
#include <pthread.h>
#include <stdlib.h>
#include <assert.h>
typedef struct Node { int job; struct Node *next; } Node;
static Node *head,*tail;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int closed,total;
static void *producer(void *p) {
    (void)p;
    for(int i=1;i<=5;i++) {
        Node *n=malloc(sizeof *n); assert(n); n->job=i; n->next=NULL;
        assert((pthread_mutex_lock(&m)) == 0);
        if(tail) tail->next=n; else head=n; tail=n;
        assert((pthread_cond_signal(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    } return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for(int jobs=0;jobs<=5;jobs++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(!head && !closed) assert((pthread_cond_wait(&cv,&m)) == 0);
        if(!head) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        Node *n=head; head=n->next; if(!head) tail=NULL;
        assert((pthread_mutex_unlock(&m)) == 0); total+=n->job; free(n);
    } abort();
}
int main(void) {
    pthread_t p,c; assert((pthread_create(&c,NULL,consumer,NULL)) == 0); assert((pthread_create(&p,NULL,producer,NULL)) == 0);
    assert((pthread_join(p,NULL)) == 0); assert((pthread_mutex_lock(&m)) == 0); closed=1;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0); assert((pthread_join(c,NULL)) == 0);
    assert(!head && !tail && total==15);
    assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Only m changes head/tail; dequeue atomically detaches a node. The consumer alone writes total and main reads it after join. While predicates handle early closure notifications and spurious wakeups; removed nodes are never accessed again by the producer.

