static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t ne=PTHREAD_COND_INITIALIZER,nf=PTHREAD_COND_INITIALIZER;
static int q[2],head,tail,count,cancelled,consumed;
static void *produce(void *p) {
    (void)p;
    for(int x=1;x<=8;x++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==2 && !cancelled) assert((pthread_cond_wait(&nf,&m)) == 0);
        if(cancelled) { assert((pthread_mutex_unlock(&m)) == 0); break; }
        q[tail]=x; tail=(tail+1)%2; ++count;
        assert((pthread_cond_signal(&ne)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    } return NULL;
}
static void *consume(void *p) {
    (void)p;
    for(int i=0;i<3;i++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==0) assert((pthread_cond_wait(&ne,&m)) == 0);
        assert(q[head]==i+1); head=(head+1)%2; --count; ++consumed;
        assert((pthread_cond_signal(&nf)) == 0); assert((pthread_mutex_unlock(&m)) == 0);
    }
    assert((pthread_mutex_lock(&m)) == 0); cancelled=1;
    assert((pthread_cond_broadcast(&nf)) == 0); assert((pthread_cond_broadcast(&ne)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
int main(void) {
    pthread_t p,c; assert((pthread_create(&p,NULL,produce,NULL)) == 0); assert((pthread_create(&c,NULL,consume,NULL)) == 0);
    assert((pthread_join(c,NULL)) == 0); assert((pthread_join(p,NULL)) == 0); assert(cancelled && consumed==3);
    assert((pthread_cond_destroy(&ne)) == 0); assert((pthread_cond_destroy(&nf)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: No new item is inserted after cancellation is observed under m. A full-buffer producer releases m in cond_wait, so the consumer can set cancelled and broadcast. Pending items are deliberately abandoned by this cancellation contract rather than silently claimed as drained.

