Plan: Carry the current node’s lock forward while acquiring its successor, and splice under both adjacent locks.

```c
#include <pthread.h>
#include <stdlib.h>
#include <assert.h>
#include <limits.h>
typedef struct Node { int key; pthread_mutex_t m; struct Node *next; } Node;
static Node tail={INT_MAX,PTHREAD_MUTEX_INITIALIZER,NULL};
static Node head={INT_MIN,PTHREAD_MUTEX_INITIALIZER,&tail};
static int keys[4]={7,2,9,4};
static void *insert(void *p) {
    Node *n=malloc(sizeof *n); assert(n); n->key=*(int *)p; assert((pthread_mutex_init(&n->m,NULL)) == 0);
    Node *prev=&head; assert((pthread_mutex_lock(&prev->m)) == 0);
    Node *curr=prev->next; assert((pthread_mutex_lock(&curr->m)) == 0);
    while(curr->key<n->key) {
        assert((pthread_mutex_unlock(&prev->m)) == 0); prev=curr;
        curr=prev->next; assert((pthread_mutex_lock(&curr->m)) == 0);
    }
    n->next=curr; prev->next=n;
    assert((pthread_mutex_unlock(&curr->m)) == 0); assert((pthread_mutex_unlock(&prev->m)) == 0); return NULL;
}
int main(void) {
    pthread_t t[4]; for(int i=0;i<4;i++) assert((pthread_create(&t[i],NULL,insert,&keys[i])) == 0);
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    int previous=INT_MIN,count=0; Node *n=head.next;
    while(n!=&tail) { Node *next=n->next; assert(n->key>previous); previous=n->key; ++count; assert((pthread_mutex_destroy(&n->m)) == 0); free(n); n=next; }
    assert(count==4); assert((pthread_mutex_destroy(&head.m)) == 0); assert((pthread_mutex_destroy(&tail.m)) == 0); return 0;
}
```

Why it is correct: The predecessor link cannot change while its mutex is held. Forward acquisition prevents a lock cycle; no concurrent deletion or reclamation invalidates a locked successor. Main traverses and destroys nodes only after every insertion joins.

