Plan: Allocate a unique ticket and spin until the serving ticket equals it.

```c
#include <pthread.h>
#include <assert.h>
#include <sched.h>
static unsigned issued,serving;
static int ids[4],admitted[4];
static void *visitor(void *p) {
    int id=*(int *)p; unsigned ticket=__atomic_fetch_add(&issued,1,__ATOMIC_RELAXED);
    while(__atomic_load_n(&serving,__ATOMIC_ACQUIRE)!=ticket) sched_yield();
    admitted[ticket]=id;
    __atomic_store_n(&serving,ticket+1,__ATOMIC_RELEASE); return NULL;
}
int main(void) {
    pthread_t t[4]; int seen[4]={0};
    for(int i=0;i<4;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,visitor,&ids[i])) == 0); }
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    for(int i=0;i<4;i++) { assert(admitted[i]>=0 && admitted[i]<4); ++seen[admitted[i]]; }
    for(int i=0;i<4;i++) assert(seen[i]==1);
    assert(__atomic_load_n(&serving,__ATOMIC_RELAXED)==4); return 0;
}
```

Why it is correct: Only one ticket matches serving, providing mutual exclusion. Release/acquire hands off completed critical sections in ticket order. Finite ticket counts avoid wraparound, and progress assumes earlier ticket holders run; issuance order is not guaranteed to match pthread_create order.

