Plan: Check an atomic cancellation predicate at explicit safe points and retain a finite loop limit.

```c
#include <pthread.h>
#include <stdio.h>
#include <assert.h>
#include <stdatomic.h>
static atomic_int stop;
typedef struct { unsigned steps; } Result;
static Result result[3];
static void *work(void *p) {
    Result *r=p;
    for(unsigned i=0;i<10000;i++) {
        if(atomic_load_explicit(&stop,memory_order_acquire)) break;
        ++r->steps;
    } return NULL;
}
int main(void) {
    pthread_t t[3]; atomic_init(&stop,0);
    for(int i=0;i<3;i++) assert((pthread_create(&t[i],NULL,work,&result[i])) == 0);
    atomic_store_explicit(&stop,1,memory_order_release);
    for(int i=0;i<3;i++) { assert((pthread_join(t[i],NULL)) == 0); assert(result[i].steps<=10000); }
    puts("finite workers stopped or completed"); return 0;
}
```

Why it is correct: stop has no plain-flag data race. Each result has one worker owner and main joins before reading. No resource is held across a cancellation check, so an early exit cannot leak a lock or permit; a worker that finishes before cancellation is also valid.

